/**
 * Squirrelcade's console marks (D185): its own drawings after each console's hardware and symbols (a pad, a screen, a
 * shape; no official logo files), approved by the owner on 2026-10-26. Each is drawn on a 24-unit-high grid with its
 * own width, in its console's color (currentColor), the cuts in a shape (a D-pad, a screen) as masks so a mark works on
 * any surface, the digits and words outlined (Arimo, Apache 2.0). "__ID__" is replaced by an id of each use's own.
 * A console without a drawing keeps its pixel mark (CONSOLE_MARKS, D175). Generated from the owner's approved draft:
 * edit the drawings there and generate again, or edit a mark here by hand.
 */
export interface MarkDrawing {
  name: string;
  /** Its width on the 24-unit-high grid. */
  width: number;
  color: string;
  maker: string;
  /** The SVG's insides, its own colors as currentColor (a few fixed: a Neo Geo's buttons, the 3DO's shapes). */
  svg: string;
  /** Drawn otherwise when you don't have it (PC's dark screen). */
  faded?: string;
}

